function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function beep() { 
  const snd = new Audio("data:audio/wav;base64,");
  snd.play();
}

const areas = [
    "B11",
    "B:11-15"
]

let flag = true;
let isContinue = true;
let scannedAreas = [];
while(flag) {
    if (areas.length === scannedAreas.length) {
        scannedAreas = [];
    }

    const targetAreas = areas.filter((_area) => !scannedAreas.includes(_area));
    const _idx = Math.floor(Math.random() * targetAreas.length);
    const targetArea = targetAreas[_idx];
}

const count = 3;
const SEAT_REGEX = /^(?<seat>[A-Za-z]+)(?<seatNumber>\d+)$/;
let _targets = document.querySelectorAll('button[class*="seatMap_seatNumber"][class*="seatMap_seatNormal"]:not([class*="seatMap_seatDisabled"], [class*="seatMap_active"])')
let selectedSeats = []
for (const _target of _targets) {
    // if (_target.closest(".rzpp-mini-map")) continue;

    const targetRegex = _target.innerText.match(SEAT_REGEX);
    const { seat, seatNumber } = targetRegex.groups

    if (selectedSeats.length > 0) {
        const lastSeat = selectedSeats[selectedSeats.length - 1]
        if (lastSeat.seat != seat || lastSeat.number + 1 != seatNumber) {
            selectedSeats = []
        }
    }
    selectedSeats.push({ seat: seat, number: parseInt(seatNumber, 10) });

    if (selectedSeats.length >= count) break;
}

console.log(selectedSeats)
if (selectedSeats.length >= count) {
    for (let i = 0; i < selectedSeats.length; i += 2) {
        let { seat, number } = selectedSeats[i];

        const element = [...document.querySelectorAll('button[class*="seatMap_seatNumber"][class*="seatMap_seatNormal"]:not([class*="seatMap_seatDisabled"]) > span')]
            .find(span => span.textContent.trim() === `${seat}${number}`);
        element.click();
        await sleep(100);
    }
}
